training=f'''import json
from fixture_workflow import supplied_workflow

def train(dataset_path={dataset!r}, threshold={default!r}):
    result = supplied_workflow(dataset_path=dataset_path, threshold=threshold)
    print(f"dataset_path={{dataset_path}} threshold={{threshold}} validation_accuracy={{result['validation_accuracy']}}")
    return {{"parameters": result["resolved_parameters"], "validation_accuracy": result["validation_accuracy"]}}

if __name__ == "__main__":
    with open("configuration.json") as handle:
        config = json.load(handle)
    default_run = train()
    configured_run = train(dataset_path=config["dataset_path"], threshold=config["threshold"])
    record = {{"default": default_run, "configured": configured_run}}
    with open("training_record.json", "w") as handle:
        json.dump(record, handle)
    with open("training_record.json") as handle:
        restored = json.load(handle)
    assert restored == record'''
