 item('Criterion: commit and clean-process verification. This is an illustrative inspection transcript, not a claim of cloud execution.\n'+code('git add training_script.py\ngit commit -m "Extract parameterized entry point"\ngit rev-parse --verify HEAD > retained_revision.txt\npython training_script.py > capture.log 2>&1\ncat capture.log\n# Independently inspected result: successful exit; both reported settings/results match the notebook fixture.\npython -c \'import subprocess; subprocess.run(["python", "training_script.py"], check=True)\'\n# Checked caller invocation: successful exit.')+'\nCorresponding notebook results: '+json.dumps(observed),True,'The committed revision is retained and the clean-shell capture and checked caller are inspected against the corresponding settings.'),
