choice('training_dataset_version','An authorized test overwrites the mutable dataset key after its generation and byte digest were recorded. Which verification establishes that the original snapshot remains retrievable?',[
 ('Download the recorded generation and compare the SHA-256 of its actual bytes with the original record.',True,'Explicit generation selection and byte-digest comparison verify the recorded snapshot after overwrite.'),
 ('Download the current latest key and accept it because the object name is unchanged.',False,'A mutable object name can resolve to new contents after overwrite.'),
 ('Copy the expected digest into the new download record without reading its bytes.',False,'An expected digest is not a digest computed from the retrieved bytes.'),
 ('Record only the latest object name and omit the generation.',False,'The name alone does not select the original retained version.')])
practice('training_dataset_version','Read each independent storage snippet and decide whether it meets or violates the stated snapshot-identity criterion. All storage operations are in the authorized version-enabled test bucket.',[
 item('Criterion: original byte identity, observed upload generation and availability before recording.\n'+code('import hashlib\nwith open(local_path, "rb") as handle:\n    original_digest = hashlib.sha256(handle.read()).hexdigest()\nblob = bucket.blob(object_name)\nblob.upload_from_filename(local_path)\nblob.reload()\ngeneration = blob.generation\nselected = bucket.blob(object_name, generation=generation)\nassert selected.exists()\nrecord = {"object_name": object_name, "generation": generation, "sha256": original_digest}'),True,'The digest comes from original bytes and the observed generation is checked for existence before being recorded.'),
 item('Criterion: retrieve the same generation before and after an authorized latest overwrite. Recorded snapshot:\n'+json.dumps(snap)+'\n'+code('selected = bucket.blob(record["object_name"], generation=record["generation"])\nselected.download_to_filename(download_path)\nwith open(download_path, "rb") as handle:\n    assert hashlib.sha256(handle.read()).hexdigest() == record["sha256"]\nbucket.blob(record["object_name"]).upload_from_filename("changed_latest.csv")\nselected.download_to_filename(download_path)\nwith open(download_path, "rb") as handle:\n    assert hashlib.sha256(handle.read()).hexdigest() == record["sha256"]'),True,'Both downloads explicitly use the recorded generation and verify their actual byte digests.'),
 item('Criterion: generation-qualified retrieval after overwrite.\n'+code('bucket.blob(record["object_name"]).download_to_filename(download_path)\nrecord["sha256"] = record["sha256"]'),False,'Omitting generation resolves the mutable current object, and self-assignment does not verify downloaded bytes.'),
 item('Criterion: availability before recording.\n'+code('selected = bucket.blob(object_name, generation=requested_generation)\n# No exists check or successful retrieval is performed.\nrecord = {"object_name": object_name, "generation": requested_generation, "available": True}'),False,'A requested generation must be confirmed to exist rather than merely declared available.')])
