practice('training_environment_record','Read each independent manifest snippet. Decide whether it meets or violates the named environment-record criterion. Variables named independent_* contain fresh observations, not values copied from the manifest.',[
 item('Criterion: collect actual revision, dependency pins and execution context.\n'+code('import subprocess, sys\nrevision = subprocess.run(["git", "rev-parse", "--verify", "HEAD"], check=True, capture_output=True, text=True).stdout.strip()\nfreeze = subprocess.run([sys.executable, "-m", "pip", "freeze"], check=True, capture_output=True, text=True).stdout\npins = dict(line.split("==", 1) for line in freeze.splitlines() if "==" in line)\nmanifest = {"revision": revision, "dependencies": pins, "runtime_identity": supplied_runtime_identity, "python_version": sys.version, "python_executable": sys.executable}'),True,'The record uses inspected HEAD, installed version pins and actual Python details alongside the supplied runtime identity.'),
 item('Criterion: structured JSON and independent verification.\n'+code('import json\nwith open("environment.json", "w", encoding="utf-8") as handle:\n    json.dump(manifest, handle)\nwith open("environment.json", "r", encoding="utf-8") as handle:\n    parsed = json.load(handle)\nassert parsed["revision"] == independent_revision\nassert parsed["dependencies"] == independent_dependencies\nassert parsed["runtime_identity"] == independent_runtime_identity\nassert parsed["python_version"] == independent_python_version\nassert parsed["python_executable"] == independent_python_executable'),True,'The saved JSON is parsed and every required field is compared against independent observations.'),
 item('Criterion: reject changed revision, dependency or runtime.\n'+code('def verify(parsed, independent):\n    independent.update(parsed)\n    return parsed == independent'),False,'Updating the independent observations to match the parsed record conceals changes instead of rejecting them.'),
 item('Criterion: detect any changed required environment field.\n'+code('def verify(parsed, independent):\n    return parsed["revision"] == independent["revision"]\n# Dependencies and all runtime fields are ignored.'),False,'A matching revision alone cannot detect a changed dependency version or runtime field.')])
