practice('model_version_registration','Read each independent registry excerpt. Decide whether it meets or violates the stated identity criterion. All overwrites are authorized test-bucket operations; the originating artifact record is '+json.dumps(run)+'.',[
 item('Criterion: exact run artifact and mismatch rejection before version creation.\n'+code('from mlflow import MlflowClient\nclient = MlflowClient()\nrun = client.get_run(record["run_id"])\nassert run_artifact_identity(run) == record\nblob = bucket.blob(record["key"], generation=record["generation"])\nblob.download_to_filename(record["local_path"])\nwith open(record["local_path"], "rb") as handle:\n    observed_hash = hashlib.sha256(handle.read()).hexdigest()\nif observed_hash != record["expected_hash"]:\n    return {"registered": False}\n# Only matching bytes can continue to the version-creation branch.\n# run_artifact_identity is the supplied run-record reader.'),True,'The originating run and exact generation are resolved, actual bytes are hashed and mismatch returns before any version creation.'),
 item('Criterion: create and retrieve a pinned version linked to its originating run. Matching-hash branch only.\n'+code('client.get_registered_model(record["model_name"])\nversion = client.create_model_version(name=record["model_name"], source=record["version_qualified_source"], run_id=record["run_id"])\nclient.set_model_version_tag(record["model_name"], version.version, "generation", str(record["generation"]))\nclient.set_model_version_tag(record["model_name"], version.version, "sha256", observed_hash)\nretrieved = client.get_model_version(record["model_name"], version.version)\nassert retrieved.source == record["version_qualified_source"]\nassert retrieved.run_id == record["run_id"]\nassert retrieved.tags["generation"] == str(record["generation"])\nassert retrieved.tags["sha256"] == record["expected_hash"]\nassert run_artifact_identity(client.get_run(retrieved.run_id)) == record\n# For a supplied new name, create_registered_model(name) precedes version creation.'),True,'The model exists before creation, the numeric version is retained, tags pin identity and retrieval verifies source, tags and linked run.'),
 item('Criterion: registered contents survive latest overwrite.\n'+code('bucket.blob(record["key"]).upload_from_filename("replacement_artifact.json")\nbucket.blob(record["key"], generation=int(retrieved.tags["generation"])).download_to_filename(record["local_path"])\nwith open(record["local_path"], "rb") as handle:\n    stable = hashlib.sha256(handle.read()).hexdigest() == retrieved.tags["sha256"]\nreturn {"registered": stable, "version": retrieved.version, "run_id": retrieved.run_id}'),True,'The registered generation is re-downloaded and byte-verified after overwrite, with one keyed verdict.'),
 item('Criterion: reject the mismatch fixture before creation.\n'+code('if observed_hash != record["expected_hash"]:\n    version = client.create_model_version(name=record["model_name"], source=record["version_qualified_source"], run_id=record["run_id"])\n    return {"registered": False}'),False,'Returning false after version creation is too late; mismatched bytes must create no registry version.')])
