practice('bounded_managed_training','Read each independent request or inspection snippet and decide whether it meets or violates the stated bounded-training criterion. Authorized supplied contract: '+json.dumps(managed)+'. Status statements are hypothetical inspection evidence, not actual cloud execution.',[
 item('Criterion: verified version-qualified inputs and immutable materialization before submission.\n'+code('selected = storage_client.get_object(Bucket=contract["input_bucket"], Key=contract["input_key"], VersionId=contract["input_version"])\nassert hashlib.sha256(selected["Body"].read()).hexdigest() == contract["dataset_snapshot"]["expected_hash"]\nstorage_client.copy_object(Bucket=contract["input_bucket"], Key=contract["immutable_key"], CopySource={"Bucket": contract["input_bucket"], "Key": contract["input_key"], "VersionId": contract["input_version"]})\n# The controlled destination is immutable for this job; the channel URI references it.\n# Supplied custom container reads '+managed['channel_path']+' and writes '+managed['model_output_path']+'.'),True,'Selected bytes are verified, the version is explicitly copied to a controlled immutable input and the custom container paths match the contract.'),
 item('Criterion: exactly one authorized request within the supplied limits. Shown identity-and-budget fields (other API-required platform fields are already supplied):\n'+code(json.dumps(request,indent=2))+'\n'+code('import boto3, json\nclient = boto3.client("sagemaker")\nwith open(contract["configuration_path"], "w") as handle:\n    resolved_configuration.update(shown_fields)\n    json.dump(resolved_configuration, handle)\nwith open(contract["configuration_path"]) as handle:\n    parsed_configuration = json.load(handle)\nclient.create_training_job(**parsed_configuration)\n# This branch is entered once only after successful input verification; no retry or second submission.'),True,'The single request uses the supplied image, role, immutable input, output location and permitted instance type/count/runtime, from structured parsed configuration.'),
 item('Criterion: inspect terminal completion, retrieve the matching artifact and preserve a structured execution record.\n'+code('description = client.describe_training_job(TrainingJobName=contract["job_name"])\n# Supplied inspection evidence: TrainingJobStatus is Completed.\nassert description["TrainingJobStatus"] == "Completed"\nartifact = description["ModelArtifacts"]["S3ModelArtifacts"]\nassert artifact == contract["artifact_uri"]\n# Resolve the returned URI to artifact_bucket and artifact_key.\nstorage_client.download_file(Bucket=artifact_bucket, Key=artifact_key, Filename=local_artifact)\nrecord = {"job": contract["job_name"], "dataset_snapshot": contract["dataset_snapshot"], "code_reference": contract["code_reference"], "configuration": parsed_configuration, "artifact_uri": artifact, "status": description["TrainingJobStatus"], "compute_ended": True}\nwith open("execution_record.json", "w") as handle:\n    json.dump(record, handle)\nwith open("execution_record.json") as handle:\n    restored = json.load(handle)\nassert restored == record\nassert restored["artifact_uri"] == description["ModelArtifacts"]["S3ModelArtifacts"]\n# Non-Completed branches report FailureReason when present and do not claim success.'),True,'Completed is explicitly inspected, authorized retrieval uses the verified returned artifact, and the round-tripped record links snapshot, code/configuration, job and artifact with terminal compute status.'),
 item('Criterion: terminal status confirms job-managed compute has ended.\n'+code('client.create_training_job(**resolved_configuration)\nrecord = {"status": "Completed", "compute_ended": True}\n# No describe_training_job call is made; submission is treated as completion.'),False,'Submission does not establish terminal status or that job-managed compute use has ended.'),
 item('Criterion: do not resubmit on a nonterminal status.\n'+code('description = client.describe_training_job(TrainingJobName=job_name)\nwhile description["TrainingJobStatus"] == "InProgress":\n    client.create_training_job(**resolved_configuration)\n    description = client.describe_training_job(TrainingJobName=job_name)'),False,'The loop submits again instead of only inspecting the one authorized job, violating exactly-one submission.')])
# Generate metadata and keys from planned anchors and authored excerpt predicates.
out={k:plans[k] for k in ['schema_version','path_id','batch_id']};out['kind']='interactions_part';out['tiles']=[]
checklist=[]
for tile in plans['tiles']:
 stiles=next(t for t in screens['tiles'] if t['tile_id']==tile['tile_id']);rem={}
 for r in stiles.get('remediation_steps',[]):
  for cid in r['concept_ids']:rem.setdefault(cid,[]).append(r['step_id'])
 target=[];seen=set();eligible=[s for s in tile['steps'] if s['type'] in ('check','hands_on')]
 taught=set()
 for step in tile['steps']:
  if step['type']=='explainer':taught.update(step['fact_ids'])
  if step not in eligible:continue
  cid=step['concept_ids'][0];bundle=g[cid]
  plannedcaps=[a.split('assessment:')[1] for a in step['anchors'] if '#assessment:' in a]
  measures=[{'concept_id':cid,**copy.deepcopy(a)} for a in bundle['assessment_anchors'] if a['capability'] in plannedcaps]
  assert len(measures)==len(plannedcaps)
  assert all(cid+'#'+f in taught for m in measures for f in m['fact_ids'])
  pos=eligible.index(step);difficulty='intro' if pos==0 else ('stretch' if step['type']=='hands_on' and pos>=len(eligible)-2 else 'core')
  ix={'interaction_id':'ix.'+step['step_id'],'type':step['planned_interaction_type'],'difficulty':difficulty,'grading_mode':'client','standalone':True,'measures':measures,'anchors':copy.deepcopy(step['anchors'])}
  hintmap={
   'mle.ml_training_script':['Trace where the configured values enter the function and where the executable calls sit.','Separate saved files, staged changes and retained committed revisions.'],
   'mle.training_dataset_version':['Distinguish the mutable object name from its retained generation.','Trace whether the digest is computed from actual bytes.'],
   'mle.training_environment_record':['Separate parsed manifest values from fresh independent observations.','Check revision, dependency mapping and every runtime field.'],
   'mle.experiment_reproduction':['Separate verified run inputs and process execution from outcome agreement.','Trace settings, working directory and both captured output streams.'],
   'mle.model_version_registration':['Trace the originating run through generation, byte digest and numeric registry version.','Ask what an overwrite can change and what the pinned record still identifies.'],
   'mle.model_preprocessing_package':['Trace fitted state from the trusted package into the serving prediction path.','Separate image tags from immutable identities, and runtime secrets from image/configuration literals.'],
   'mle.protected_test_comparison':['Check which actual class each error-rate denominator conditions on.','Separate frozen comparison reporting from a new selection decision.'],
   'mle.bounded_managed_training':['Separate input verification, submission and inspected terminal status.','Trace the one job through its artifact reference and structured execution record.']}
  hints=hintmap[cid]
  ix['feedback']={'correct':{'message':'Correct: the judgement follows the stated criterion and the supplied evidence.'},'incorrect':{'message':'Recheck the stated criterion against the supplied evidence. '+bundle['coverage']['learning_objective']},'hints':hints}
  if cid in rem:ix['feedback']['remediation_step_id']=rem[cid][0 if cid not in seen else min(1,len(rem[cid])-1)]
  seen.add(cid)
  if ix['type']=='choice':
   prompt,opts=C[cid];ix['public']={'prompt':prompt,'selection':'single','shuffle':True,'options':[]};ix['grading']={'correct_option_ids':[],'option_feedback':{}}
   for j,(text,ok,why) in enumerate(opts):
    oid='o'+str(j+1);ix['public']['options'].append({'option_id':oid,'text':text});ix['grading']['option_feedback'][oid]={'message':why}
    if ok:ix['grading']['correct_option_ids'].append(oid)
   assert len(ix['grading']['correct_option_ids'])==1
  elif ix['type']=='classify':
   prompt,items=H[cid];ix['public']={'prompt':prompt,'buckets':[{'bucket_id':'meets','label':'Meets the named criterion'},{'bucket_id':'violates','label':'Violates the named criterion'}],'items':[]};ix['grading']={'assignments':{},'item_feedback':{}}
   for j,(text,ok,why) in enumerate(items):
    iid='i'+str(j+1);ix['public']['items'].append({'item_id':iid,'text':text});ix['grading']['assignments'][iid]='meets' if ok else 'violates';ix['grading']['item_feedback'][iid]={'message':why}
   assert set(ix['grading']['assignments'].values())=={'meets','violates'}
   assert cid+'#practice' in ix['anchors']
  else:raise ValueError(ix['type'])
  target.append({'step_id':step['step_id'],'interaction':ix})
  checklist.append({'step_id':step['step_id'],'planned_type':True,'bare_fact_ids':True,'assessment_anchors_valid':True,'taught_by_prior_text':True,'one_answer_or_one_bucket_per_criterion':True,'wrong_answers_explained':True,'remediation_copied':True,'standalone_self_contained':True,'practice_is_inspect_and_judge':step['type']=='hands_on','data_values_derived':True})
 out['tiles'].append({'tile_id':tile['tile_id'],'interactions':target})
assert sum(len(t['interactions']) for t in out['tiles'])==sum(sum(s['type'] in ('check','hands_on') for s in t['steps']) for t in plans['tiles'])
(B/'interactions.json').write_text(json.dumps(out,indent=2)+'\n')
(B/'scratch/stage04_checklist.json').write_text(json.dumps({'items':checklist,'not_applicable':['SQL/Python solutions, expected execution results, starters and output-column pinning: no code_exercise steps are planned','dataset-backed classify source/role_map: these are inline inspect-and-judge excerpts, not dataset cell classification'],'counts':{t['tile_id']:len(t['interactions']) for t in out['tiles']}},indent=2)+'\n')
print({t['tile_id']:len(t['interactions']) for t in out['tiles']})
